/**
 * v2.0 item 10: a session with no controller attached runs on and on: through at least eight
 * phrases on the fake audio clock it is still running, and only Stop ends it, with every phrase
 * that sounded in its history. Runs against the workspace harness (port 4175), its look-ahead
 * phrases generated by the real worker.
 */
import { expect, test } from '@playwright/test'

import {
  advanceAudioBy,
  countInClickTimes,
  gotoSessionHarness,
  readyToStart,
  sessionAction,
  sessionState,
  startSession,
} from './session-helpers'
import { advanceAudioTo } from '../audio/audio-harness-helpers'

/** One four-measure phrase at the default 90 BPM, in seconds. */
const PHRASE_SECONDS = (16 * 60) / 90

// @test-link [[req_rolling_practice_session]]
// @test-link [[rule_stop_ends_session]]
test('with no controller, a session runs through eight phrases and on until Stop', async ({
  page,
}) => {
  test.setTimeout(120_000)
  await gotoSessionHarness(page)
  await readyToStart(page)
  expect(await page.evaluate(() => window.__workspaceHarness.midi.state().kind)).toBe(
    'not-requested',
  )

  await startSession(page)
  const [firstClick] = await countInClickTimes(page)
  const phraseOneAt = (firstClick ?? 0) + (4 * 60) / 90
  await advanceAudioTo(page, phraseOneAt + 0.05)

  for (let phrase = 1; phrase <= 8; phrase += 1) {
    await advanceAudioBy(page, PHRASE_SECONDS)
    expect((await sessionState(page)).phase, `after phrase ${phrase}`).toBe('running')
  }

  await sessionAction(page).click()
  const state = await sessionState(page)
  expect(state.phase).toBe('idle')
  expect(state.lastEnd?.cause).toBe('stop')
  expect(state.lastEnd?.phase).toBe('running')
  expect(state.lastEnd?.soundedPhraseCount).toBeGreaterThanOrEqual(9)
  expect(state.lastHistoryPhraseCount).toBe(state.lastEnd?.soundedPhraseCount)
})
